mapper.update:
UPDATE member
SET
    name = #{profile.name, jdbcType=VARCHAR},
    nickname = #{profile.nickname, jdbcType=VARCHAR}
WHERE no = #{memberNo, jdbcType=NUMERIC}

UPDATE member
SET password = #{password, jdbcType=VARCHAR}
WHERE no = #{memberNo, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM member
WHERE no = #{memberNo, jdbcType=NUMERIC}
AND role = 'USER'

mapper.select:
SELECT COUNT(*)
FROM member
WHERE nickname = #{nickname, jdbcType=VARCHAR}
AND no != #{memberNo, jdbcType=NUMERIC}

SELECT COUNT(*)
FROM member
WHERE email = #{email, jdbcType=VARCHAR}
AND no != #{memberNo, jdbcType=NUMERIC}
